// @req: REQ-011
const assert = require('assert');
const unalib = require('../../libs/unalib');

describe('REQ-011 (Unit) — Exigencia de nombre de usuario en unalib', function () {
  it('debe rechazar mensajes con nombre de usuario vacío', function () {
    const res = unalib.validateMessage({ mensaje: 'Mensaje legítimo', nombre: '', color: '#000000' });
    assert.strictEqual(res === false || res === null || (res && res.valid === false) || (res && !res.nombre), true, 'Nombre vacío debe ser invalidado');
  });
  it('debe rechazar mensajes con nombre de solo espacios en blanco', function () {
    const res = unalib.validateMessage({ mensaje: 'Mensaje legítimo', nombre: '    ', color: '#000000' });
    assert.strictEqual(res === false || res === null || (res && res.valid === false) || (res && !res.nombre?.trim()), true, 'Nombre de solo espacios debe ser invalidado');
  });
});

