// @req: REQ-011
const { test, expect } = require('@playwright/test');

test.describe('REQ-011 (E2E) — Exigencia de nombre de usuario en navegador', () => {
  test('al enviar mensaje con username vacío no debe agregar transcript y debe notificar al usuario', async ({ page }) => {
    await page.goto('/');
    let dialogTriggered = false;
    page.on('dialog', async dialog => {
      dialogTriggered = true;
      await dialog.dismiss();
    });
    await page.locator('#nombre').fill('');
    await page.locator('#m').fill('Mensaje válido de prueba');
    await page.locator('button[type="submit"]').click();
    const nameValue = await page.locator('#nombre').inputValue();
    expect(nameValue.trim()).toBe('');
  });
});
